local DailyOfferDialog = Class('DailyOfferDialog')
function DailyOfferDialog:__init()
    
    self.isOpen = false
end

function DailyOfferDialog:__delete()
    
    self.isOpen = true
    Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
end

function DailyOfferDialog:Awake()
    self:InitData()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))

end
function DailyOfferDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        local data = parameters.data
        if isNull(data) then
            return
        end
        self:Request()
    end
end

function DailyOfferDialog:Start()
    SetButtonAction(self.FontStyleButton.gameObject ,Bind(self,self.AllDraw))
    SetButtonAction(self.ImgFrame.gameObject ,Bind(self,self.BuyWeeklyCardClick))
    SetButtonAction(self.BtnRole, Bind(self, self.BtnRoleClickHandler))
    SetButtonAction(self.BtnLock,function ()
        GameUtils.Toast(localize("今日无法购买"))
    end)
end
