function DailyOfferDialog:PlayRoleEntryAnimation()
    local type = nil
    if not self.isOpen then
        self.isOpen = true
        type = SpineAnimationType.OPEN
    else
        type = SpineAnimationType.SWITCH
    end
    self:PlayRoleAnimation(type)
end
function DailyOfferDialog:Refresh()
    self:PlayRoleEntryAnimation()
