end
function DailyOfferDialog:RefreshDailyHome()
    self:RefreshItemId()
    self:RefreshWeeklyItemId()
end
--region init
function DailyOfferDialog:InitData()
    local setting = CfUtils.GetCf(AutoIds.IdSetting603, "StoreRoleDialogueVo")
    ---@type StoreRoleDialogueVo[]
    local config = setting:GetAll()
    self._aniConfig = {}
    for i, v in ipairs(checkTable(config)) do
        if self._aniConfig[v.type] then
            table.insert(self._aniConfig[v.type], v)
        else
            self._aniConfig[v.type] = {v}
        end
    end
end
function DailyOfferDialog:BuyWeeklyCardClick()
    local isShowBuy = true
    local comp =  StoreUtils.GetOverseaStoreComp()
    local dailyOfferData =  comp._storeHomeDojo.dailyOffer
    for i, dojo in pairs(dailyOfferData) do
        ---@type DailyOfferVo
        local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dojo.dailyOfferId)
        local DAILY_OFFER_TYE = {
            FREE = 0,
            DAILY = 1 ,
            WEEKLY = 2
        }
        if checkInt(dailyOfferVo.giftType) == DAILY_OFFER_TYE.DAILY then
            if checkInt(dojo.isDraw) >= 1 then
                isShowBuy = false
                break
            end
        end
    end
    if not isShowBuy then
        GameUtils.Toast(localize("今日无法购买")) 
        return
    end
    ---@type DailyOfferDojo
    local dailyOfferDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferWeeklyDojo()
    if checkInt(dailyOfferDojo.stock) == 0 or dailyOfferDojo:GetLeftSecond() <= 0 then
        if dailyOfferDojo:IsGoodExchange() then
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            local currrency = Constants.Currency.FreeDiamondId
            local price = 0 
            for goodsId, v in pairs(dailyOfferDojo.prices) do
                price = v.current
                currrency = checkInt(goodsId) 
                break
            end
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency =  currrency,
                current = price,
            }, function(isSuccess)
                isSuccess = checkBool(isSuccess)
                if not isSuccess then
                    return
                end
                ----请求兑换的逻辑
                GameUtils.Request(Interfaces.OverseaMallDailySpecialBuy,{
                    productId  = dailyOfferDojo.dailyOfferId,
                    currency = currrency,
                    num = 1,
                }, function(request,response)
                    if checkInt(response.errCode) == 0 then
                        local oneReawards = response.data.rewards  or {}
                        local rewards = clone(oneReawards)
                        rewards[#rewards+1] = {
                            goodsId = currrency ,
                            num = -price,
                            productId = checkNumber(dailyOfferData.dailyOfferId)
                        }
                        GoodsUtils.DrawRewards(rewards)
                        if #oneReawards > 0 then
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = oneReawards, cb = function()
                                self:Request()
                            end  } })
                        else 
                            self:Request()
                        end
                    end
                end )
            end)
        else 
            local SDKService = import('Game.Entry.SDKService')
            SDKService:GetInstance():PayMoney({
                productId = dailyOfferDojo.productId,
                channelProductId = dailyOfferDojo.channelProductId,
                productDesc = localize("每日特惠"),
                payAmount = dailyOfferDojo.price,
                data = dailyOfferDojo
            })    
        end
       
    end
end

function DailyOfferDialog:AllDraw()
    local dailyOfferDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferWeeklyDojo()
    if checkInt(dailyOfferDojo.isDraw) == 2 then
        GameUtils.Toast(localize("商品已售罄"))
        return
    end

    if  checkInt(dailyOfferDojo.isDraw) == 1 then
        local DAILY_OFFER_TYE = {
            FREE = 0,
            DAILY = 1 ,
            WEEKLY = 2
        }
        local isDraw = false
        local comp =  StoreUtils.GetOverseaStoreComp()
        local data =  comp._storeHomeDojo.dailyOffer
        for i, dojo in pairs(data) do
            ---@type DailyOfferVo
            local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dojo.dailyOfferId)
            if checkInt(dailyOfferVo.giftType) == DAILY_OFFER_TYE.DAILY then
                if checkInt(dojo.isDraw) == 1 then
                    isDraw = true
                end
            end
        end
        if not isDraw then
            GameUtils.Toast(localize("商品已售罄"))
            return
        end
    end


    GameUtils.Request(Interfaces.StoreDrawDailyOffer,{ dailyOfferId = dailyOfferDojo.dailyOfferId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local UIModule = CS.Engine.UI.UIModule
        local data = response.data
        GoodsUtils.DrawRewards(checkTable(data.rewards), true)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })
        xRecord.record("5-015", string.format("click_pack_%d", checkInt(dailyOfferDojo.dailyOfferId)))
        self:Request()
    end)
end

function DailyOfferDialog:Request()
    GameUtils.Request(Interfaces.StoreDailyOffer,{},function(request, response)
        if checkNumber(response.errCode) == 0 then
            
            local comp =  StoreUtils.GetOverseaStoreComp()
            comp:InitialDailyOfferData(response.data.dailyOffer)
            self:Refresh()
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
        end
    end)
end

function DailyOfferDialog:RefreshWeeklyItemId()
    ---@type DailyOfferDojo
    local dailyOfferDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferWeeklyDojo()
    CfUtils.FillText(self.TxtNumber , dailyOfferDojo.price)
    local isDraw = false
    local comp =  StoreUtils.GetOverseaStoreComp()
    local dailyOfferData =  comp._storeHomeDojo.dailyOffer
    if checkInt(dailyOfferDojo.isDraw) == 1 then
        isDraw = true
        local DAILY_OFFER_TYE = {
            FREE = 0,
            DAILY = 1 ,
            WEEKLY = 2
        }
        for i, dojo in pairs(dailyOfferData) do
            ---@type DailyOfferVo
            local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dojo.dailyOfferId)
            if checkInt(dailyOfferVo.giftType) == DAILY_OFFER_TYE.DAILY then
                if checkInt(dojo.isDraw) == 1 then
                    isDraw = false
                end
            end
        end
    end

    KTool.SetActive(self.TxtSymbol,false)
    if  isDraw then
        KTool.SetActive(self.PriceGroup,false)
        KTool.SetActive(self.ReceiveGroup,true)
        KTool.SetActive(self.FontStyleButton, false)
        local payData = CfUtils.GetPayData(dailyOfferDojo.price ,nil)
        if dailyOfferDojo:IsGoodExchange() then
            local currency = Constants.Currency.FreeDiamondId
            local num = 0 
            for goodsId, v in pairs(dailyOfferDojo.prices) do
                num = v.current
                currency =  goodsId
                break
            end
            CfUtils.FillText(self.TxtNumber ,num)
        else     
            if isNotNull(payData.price) then
                CfUtils.FillText(self.TxtNumber , payData.price) 
            end
        end
        KTool.SetActive(self.TxtState.gameObject , false)
        -- CfUtils.FillText(self.TxtState,localize("剩余可领_num1_/_num2_",{_num1_ = dailyOfferDojo.stock,_num2_ = 7}) )
    else
        if checkInt(dailyOfferDojo.isDraw) == 1 then
            KTool.SetActive(self.PriceGroup,false)
            KTool.SetActive(self.ReceiveGroup,true)
        elseif checkInt(dailyOfferDojo.isDraw) == 2 then
            KTool.SetActive(self.PriceGroup,false)
            KTool.SetActive(self.ReceiveGroup,true)
            KTool.SetActive(self.FontStyleButton, false)
        else
            local isShowBuy = true
            for i, dojo in pairs(dailyOfferData) do
                ---@type DailyOfferVo
                local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dojo.dailyOfferId)
                local DAILY_OFFER_TYE = {
                    FREE = 0,
                    DAILY = 1 ,
                    WEEKLY = 2
                }
                if checkInt(dailyOfferVo.giftType) == DAILY_OFFER_TYE.DAILY then
                    if checkInt(dojo.isDraw) >= 1 then
                        isShowBuy = false
                        break
                    end
                end
            end
            if  not isShowBuy then
                KTool.SetActive(self.PriceGroup,false)
                KTool.SetActive(self.BtnLock,true) 
                KTool.SetActive(self.ReceiveGroup,false)
                KTool.SetActive(self.ImgBlack, false)
            else 
                KTool.SetActive(self.ImgBlack, false)
                KTool.SetActive(self.PriceGroup,true)
                KTool.SetActive(self.ReceiveGroup,false)
            end
        end
        -- CfUtils.FillText(self.TxtNumber , dailyOfferDojo.price)
        local payData = CfUtils.GetPayData(dailyOfferDojo.price ,nil)
        if dailyOfferDojo:IsGoodExchange() then
            local currency = Constants.Currency.FreeDiamondId
            local num = 0 
            local originPrice = 0 
            for goodsId, v in pairs(dailyOfferDojo.prices) do
                num = v.current
                currency =  goodsId
                originPrice = checkInt(v.original) 
                break
            end
            local goodsPath = GoodsConfMgr:GetInstance():GetPhotoPathById(currency)
            CfUtils.FillImage(self.ImgIcon.gameObject , goodsPath)
            KTool.SetActive(self.ImgIcon.gameObject  ,true) 
            
            CfUtils.FillText(self.TxtBuy ,num)
            if originPrice > 0 then
                CfUtils.FillImage(self.ImgIcon2.gameObject , goodsPath)
                KTool.SetActive(self.ImgIcon2.gameObject  ,true) 
                CfUtils.FillText(self.TxtNumber ,originPrice)
            else
                KTool.SetActive(self.Price2 , false)    
            end
        else
            CfUtils.FillText(self.TxtBuy , payData.displayPrice)     
             ---@type DailyOfferVo
            local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dailyOfferDojo.dailyOfferId)
            if checkInt(dailyOfferVo.originalPrice) > 0 then
                local payData = CfUtils.GetPayData(dailyOfferVo.originalPrice ,nil)
                CfUtils.FillText(self.TxtNumber , payData.displayPrice)
            else 
                KTool.SetActive(self.TxtNumber , false)    
            end  
        end
        -- CfUtils.FillText(self.TxtSymbol , payData.currencySymbol)
        CfUtils.FillText(self.TxtState,localize("剩余可领_num1_/_num2_",{_num1_ = dailyOfferDojo.stock ,_num2_ = 1}) )
    end
end

--region handler
---看板娘点击回调
function DailyOfferDialog:BtnRoleClickHandler()
    self:PlayRoleClickAnimation()
end

---播放看板娘点击动画
function DailyOfferDialog:PlayRoleClickAnimation()
    local type = SpineAnimationType.CLICK
    self:PlayRoleAnimation(type)
end

---播放看板娘动画
---@param type  integer 动画类型
function DailyOfferDialog:PlayRoleAnimation(type)
    local index = math.random(1, #self._aniConfig[type])
    local data = self._aniConfig[type][index]
    self.isLock = true
    CfUtils.PlaySpine(self.Spine, data.action, false)
    self.Spine.AnimationState:AddAnimation(0, 'idle', true, 0)
    CfUtils.FillText(self.DialogueTxt, data.dialogue)
end

function DailyOfferDialog:RefreshItemId()
    local AdvertisingFigure2 = self.AdvertisingFigure2
    for i =1 ,4 do
        local item = AdvertisingFigure2:Find("Item" .. i)
        ---@type OverseaStoreComponent
        local comp =  StoreUtils.GetOverseaStoreComp()
        local data =  comp._storeHomeDojo.dailyOffer[i]
        if not isNull(data) then
            ---@type DailyOfferItem
            local env = CfUtils.GetLuaScr(item.gameObject, "Game.OverseaStore.Daily.DailyOfferItem")
            env:RefreshDailyOfferUI(data.dailyOfferId, self)
        end
    end
end

function DailyOfferDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function DailyOfferDialog:RefreshCurrencyBar()
    ---@type OverseaStoreMgr
    local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
    local currencyList = {Constants.Currency.FreeDiamondId}
    if OverseaStoreMgr:IsSecondaryCurrencyEnable() then
        table.insert(currencyList, 1, Constants.Currency.PayDiamondId)
    end
    CfUtils.RefreshTopGoods(currencyList)
end

return DailyOfferDialog